SELECT COUNT(*) FROM app_ai_provider_deployment
WHERE account_id = #{accountId}
  AND capability = #{capability}
  AND model_name = #{modelName}
  AND voice_name = #{voiceName}
  AND id != #{excludeId}

mapper.update:
UPDATE app_ai_provider_deployment
SET circuit_open_until = #{leaseUntil}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND consecutive_failures >= failure_threshold
  AND circuit_open_until IS NOT NULL
  AND circuit_open_until <= #{now}
